insert into public.questions (id, code, subject_id, topic_id, level, difficulty, board_id, year, qtype, theme, statement, explanation, hint, source, status, updated_at) values
  ('e2000000-0000-4000-a000-00000000157d', 'CO-MAT-01774', 3, 157, 'concurso', 3, 66, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma estacionamento oferece dois planos: A, com taxa fixa de R$ 50,00 e R$ 9,00 por unidade, e B, com taxa fixa de R$ 215,00 e R$ 3,00 por unidade (as unidades são horas). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 215 + 3x < 50 + 9x ⇔ 6x > 165 ⇔ x > 27,5. O menor número inteiro é 28.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000157e', 'CO-MAT-01775', 3, 157, 'concurso', 3, 66, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma locadora de carros oferece dois planos: A, com taxa fixa de R$ 20,00 e R$ 5,50 por unidade, e B, com taxa fixa de R$ 140,00 e R$ 2,50 por unidade (as unidades são quilômetros). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 140 + 2,5x < 20 + 5,5x ⇔ 3x > 120 ⇔ x > 40. O menor número inteiro é 41.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000157f', 'CO-MAT-01776', 3, 159, 'concurso', 2, 66, 2026, 'multiple_choice', 'Divisão proporcional', 'Caio, Amanda e Henrique investiram num negócio, respectivamente, nas proporções 2, 3 e 4. O lucro de R$ 29.700,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Henrique?', 'Total de partes: 2 + 3 + 4 = 9. Cada parte vale R$ 29.700,00/9 = R$ 3.300,00. Henrique recebe 4 × R$ 3.300,00 = R$ 13.200,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001580', 'CO-MAT-01777', 3, 159, 'concurso', 2, 66, 2026, 'multiple_choice', 'Divisão proporcional', 'Pedro, Olívia e Letícia investiram num negócio, respectivamente, nas proporções 4, 3 e 3. O lucro de R$ 20.000,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Pedro?', 'Total de partes: 4 + 3 + 3 = 10. Cada parte vale R$ 20.000,00/10 = R$ 2.000,00. Pedro recebe 4 × R$ 2.000,00 = R$ 8.000,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001581', 'CO-MAT-01778', 3, 159, 'concurso', 2, 66, 2026, 'multiple_choice', 'Divisão proporcional', 'Carla, Tainá e Pedro investiram num negócio, respectivamente, nas proporções 3, 2 e 5. O lucro de R$ 2.000,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Tainá?', 'Total de partes: 3 + 2 + 5 = 10. Cada parte vale R$ 2.000,00/10 = R$ 200,00. Tainá recebe 2 × R$ 200,00 = R$ 400,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001582', 'CO-MAT-01779', 3, 159, 'concurso', 2, 66, 2026, 'multiple_choice', 'Divisão proporcional', 'Pedro, Paulo e Vitor investiram num negócio, respectivamente, nas proporções 3, 3 e 4. O lucro de R$ 17.000,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Vitor?', 'Total de partes: 3 + 3 + 4 = 10. Cada parte vale R$ 17.000,00/10 = R$ 1.700,00. Vitor recebe 4 × R$ 1.700,00 = R$ 6.800,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001583', 'CO-MAT-01780', 3, 159, 'concurso', 2, 66, 2026, 'multiple_choice', 'Divisão proporcional', 'Samuel, Mariana e Amanda investiram num negócio, respectivamente, nas proporções 2, 1 e 5. O lucro de R$ 27.200,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Mariana?', 'Total de partes: 2 + 1 + 5 = 8. Cada parte vale R$ 27.200,00/8 = R$ 3.400,00. Mariana recebe 1 × R$ 3.400,00 = R$ 3.400,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001584', 'CO-MAT-01781', 3, 159, 'concurso', 2, 66, 2026, 'multiple_choice', 'Divisão proporcional', 'Beatriz, Ana e Samuel investiram num negócio, respectivamente, nas proporções 3, 6 e 4. O lucro de R$ 29.900,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Beatriz?', 'Total de partes: 3 + 6 + 4 = 13. Cada parte vale R$ 29.900,00/13 = R$ 2.300,00. Beatriz recebe 3 × R$ 2.300,00 = R$ 6.900,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001585', 'CO-MAT-01782', 3, 160, 'concurso', 2, 66, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 3, prova 2 tem peso 3 e o trabalho tem peso 4. Samuel tirou 3,5, 10 e 8, nessa ordem. Qual foi a média final?', 'Média ponderada = (3,5·3 + 10·3 + 8·4)/(3 + 3 + 4) = 72,5/10 = 7,25.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001586', 'CO-MAT-01783', 3, 160, 'concurso', 2, 66, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 3, prova 2 tem peso 3 e o trabalho tem peso 4. Rafaela tirou 7, 3,5 e 3,5, nessa ordem. Qual foi a média final?', 'Média ponderada = (7·3 + 3,5·3 + 3,5·4)/(3 + 3 + 4) = 45,5/10 = 4,55.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001587', 'CO-MAT-01784', 3, 160, 'concurso', 2, 66, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 1, prova 2 tem peso 2 e o trabalho tem peso 2. Isabela tirou 6, 3 e 8, nessa ordem. Qual foi a média final?', 'Média ponderada = (6·1 + 3·2 + 8·2)/(1 + 2 + 2) = 28/5 = 5,6.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001588', 'CO-MAT-01785', 3, 160, 'concurso', 2, 66, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 1, prova 2 tem peso 1 e o trabalho tem peso 2. Mateus tirou 9,5, 9,5 e 8, nessa ordem. Qual foi a média final?', 'Média ponderada = (9,5·1 + 9,5·1 + 8·2)/(1 + 1 + 2) = 35/4 = 8,75.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001589', 'CO-MAT-01786', 3, 160, 'concurso', 2, 66, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 3, prova 2 tem peso 3 e o trabalho tem peso 4. Karina tirou 4, 6,5 e 5, nessa ordem. Qual foi a média final?', 'Média ponderada = (4·3 + 6,5·3 + 5·4)/(3 + 3 + 4) = 51,5/10 = 5,15.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000158a', 'CO-MAT-01787', 3, 160, 'concurso', 2, 66, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 1, prova 2 tem peso 1 e o trabalho tem peso 2. Tainá tirou 6,5, 3,5 e 7,5, nessa ordem. Qual foi a média final?', 'Média ponderada = (6,5·1 + 3,5·1 + 7,5·2)/(1 + 1 + 2) = 25/4 = 6,25.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000158b', 'CO-MAT-01788', 3, 165, 'concurso', 2, 66, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Diego gasta R$ 90,00 para produzir um bolo de pote e quer ter lucro de 60% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 60% de R$ 90,00 = R$ 54,00. Preço de venda: R$ 90,00 × 1,6 = R$ 144,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000158c', 'CO-MAT-01789', 3, 165, 'concurso', 2, 66, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Mateus gasta R$ 180,00 para produzir um bolo de pote e quer ter lucro de 40% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 40% de R$ 180,00 = R$ 72,00. Preço de venda: R$ 180,00 × 1,4 = R$ 252,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000158d', 'CO-MAT-01790', 3, 165, 'concurso', 2, 66, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Gabriela gasta R$ 145,00 para produzir um bolo de pote e quer ter lucro de 30% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 30% de R$ 145,00 = R$ 43,50. Preço de venda: R$ 145,00 × 1,3 = R$ 188,50.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000158e', 'CO-MAT-01791', 3, 165, 'concurso', 2, 66, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Mateus gasta R$ 240,00 para produzir uma camiseta estampada e quer ter lucro de 25% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 25% de R$ 240,00 = R$ 60,00. Preço de venda: R$ 240,00 × 1,25 = R$ 300,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000158f', 'CO-MAT-01792', 3, 165, 'concurso', 2, 66, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Thiago gasta R$ 190,00 para produzir uma camiseta estampada e quer ter lucro de 60% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 60% de R$ 190,00 = R$ 114,00. Preço de venda: R$ 190,00 × 1,6 = R$ 304,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001590', 'CO-MAT-01793', 3, 165, 'concurso', 2, 66, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Thiago gasta R$ 250,00 para produzir um kit de maquiagem e quer ter lucro de 30% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 30% de R$ 250,00 = R$ 75,00. Preço de venda: R$ 250,00 × 1,3 = R$ 325,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001591', 'CO-MAT-01794', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = 3x − 2, qual é o valor de f⁻¹(13)?', 'f⁻¹(13) é o x tal que f(x) = 13: 3x  − 2 = 13 ⇒ x = 5.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001592', 'CO-MAT-01795', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = −x + 6, qual é o valor de f⁻¹(7)?', 'f⁻¹(7) é o x tal que f(x) = 7: −1x  + 6 = 7 ⇒ x = −1.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001593', 'CO-MAT-01796', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = 5x − 1, qual é o valor de f⁻¹(14)?', 'f⁻¹(14) é o x tal que f(x) = 14: 5x  − 1 = 14 ⇒ x = 3.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001594', 'CO-MAT-01797', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = −5x + 8, qual é o valor de f⁻¹(18)?', 'f⁻¹(18) é o x tal que f(x) = 18: −5x  + 8 = 18 ⇒ x = −2.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001595', 'CO-MAT-01798', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = 2x + 3 e g(x) = 3x + 4, o valor de f(g(4)) é:', 'Primeiro g(4) = 16. Depois f(16) = 35.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001596', 'CO-MAT-01799', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = 4x + 5, qual é o valor de f⁻¹(−11)?', 'f⁻¹(−11) é o x tal que f(x) = −11: 4x  + 5 = −11 ⇒ x = −4.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001597', 'CO-MAT-01800', 3, 167, 'concurso', 3, 66, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = −5x + 3 e g(x) = 3x + 4, o valor de f(g(1)) é:', 'Primeiro g(1) = 7. Depois f(7) = −32.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001598', 'CO-MAT-01801', 3, 168, 'concurso', 2, 66, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (4,8 × 10²) · (5 × 10¹), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 4,8 · 5 = 24 e 10² · 10¹ = 10³. Ajustando para mantissa entre 1 e 10: 2,4 × 10⁴.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001599', 'CO-MAT-01802', 3, 168, 'concurso', 2, 66, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (8,7 × 10⁰) · (2 × 10¹), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 8,7 · 2 = 17,4 e 10⁰ · 10¹ = 10¹. Ajustando para mantissa entre 1 e 10: 1,74 × 10².', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000159a', 'CO-MAT-01803', 3, 168, 'concurso', 2, 66, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (6,3 × 10¹) · (1,5 × 10¹), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 6,3 · 1,5 = 9,45 e 10¹ · 10¹ = 10². Ajustando para mantissa entre 1 e 10: 9,45 × 10².', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000159b', 'CO-MAT-01804', 3, 168, 'concurso', 2, 66, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (8,1 × 10¹⁰) · (4 × 10²), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 8,1 · 4 = 32,4 e 10¹⁰ · 10² = 10¹². Ajustando para mantissa entre 1 e 10: 3,24 × 10¹³.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000159c', 'CO-MAT-01805', 3, 168, 'concurso', 2, 66, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (1,3 × 10⁻⁶) · (1,5 × 10⁷), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 1,3 · 1,5 = 1,95 e 10⁻⁶ · 10⁷ = 10¹. Ajustando para mantissa entre 1 e 10: 1,95 × 10¹.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000159d', 'CO-MAT-01806', 3, 168, 'concurso', 2, 66, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (2,6 × 10⁻⁵) · (3 × 10⁻²), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 2,6 · 3 = 7,8 e 10⁻⁵ · 10⁻² = 10⁻⁷. Ajustando para mantissa entre 1 e 10: 7,8 × 10⁻⁷.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000159e', 'CO-MAT-01807', 3, 169, 'concurso', 3, 66, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 2^(4x − 2) = 64?', '64 = 2⁶. Igualando os expoentes: 4x − 2 = 6 ⇒ x = 2.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000159f', 'CO-MAT-01808', 3, 169, 'concurso', 3, 66, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 5^(−2x − 5) = 1/5?', '1/5 = 5⁻¹. Igualando os expoentes: −2x − 5 = −1 ⇒ x = −2.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000015a0', 'CO-MAT-01809', 3, 169, 'concurso', 3, 66, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 3^(2x + 5) = 2.187?', '2.187 = 3⁷. Igualando os expoentes: 2x + 5 = 7 ⇒ x = 1.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000015a1', 'CO-MAT-01810', 3, 169, 'concurso', 3, 66, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 5^(3x − 1) = 25?', '25 = 5². Igualando os expoentes: 3x − 1 = 2 ⇒ x = 1.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000015a2', 'CO-MAT-01811', 3, 169, 'concurso', 3, 66, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 3^(−2x + 3) = 27?', '27 = 3³. Igualando os expoentes: −2x + 3 = 3 ⇒ x = 0.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000015a3', 'CO-MAT-01812', 3, 169, 'concurso', 3, 66, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 5^(−3x − 4) = 25?', '25 = 5². Igualando os expoentes: −3x − 4 = 2 ⇒ x = −2.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo dos concursos do Pará (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
