  ('e2000000-0000-4000-a000-00000000176f', 'CO-FIS-00558', 6, 519, 'medio', 4, 25, 2026, 'multiple_choice', 'Cordas e tubos sonoros', 'Uma corda de violão de 1 m, presa nas duas extremidades, tem ondas que se propagam a 480 m/s. Qual é a frequência do 4º harmônico?', 'Na corda presa nas pontas, fₙ = n·v/(2L). f4 = 4·480/(2·1) = 960 Hz.', 'Corda presa nas duas pontas: o fundamental tem comprimento de onda igual a 2L.', 'Questão autoral da Educa Mais. Referência de estilo: UFMG. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001770', 'CO-FIS-00559', 6, 519, 'medio', 4, 26, 2026, 'multiple_choice', 'Cordas e tubos sonoros', 'Uma corda de violão de 1,2 m, presa nas duas extremidades, tem ondas que se propagam a 360 m/s. Qual é a frequência do 3º harmônico?', 'Na corda presa nas pontas, fₙ = n·v/(2L). f3 = 3·360/(2·1,2) = 450 Hz.', 'Corda presa nas duas pontas: o fundamental tem comprimento de onda igual a 2L.', 'Questão autoral da Educa Mais. Referência de estilo: PAS/UnB. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z')
